css:
.shiftsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2e22;
    background: linear-gradient(160deg, #f3f7ee 0%, #e8f1e2 100%);
    border-radius: 18px;
}

.shiftsim-container * {
    box-sizing: border-box;
}

.shiftsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f5135 0%, #2f7a45 55%, #4ea35c 100%);
    color: #f4fbf0;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 81, 53, 0.30);
}

.shiftsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.shiftsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d7f0c8;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.shiftsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e4f4dc;
}

.shiftsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c5a3a;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.shiftsim-period-counter #currentDay,
.shiftsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5135;
}

.shiftsim-round-name {
    background: #d4ecc6;
    color: #1f5135;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.shiftsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4413;
    background: #fbe9d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.shiftsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.shiftsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
    border-top: 4px solid #4ea35c;
}

.shiftsim-card-uptake { border-top-color: #2f7a45; }
.shiftsim-card-retention { border-top-color: #1d7d8c; }
.shiftsim-card-credibility { border-top-color: #b07d18; }
.shiftsim-card-cpc { border-top-color: #6a4fb0; }

.shiftsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5e7a64;
}

.shiftsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5135;
}

.shiftsim-card-uptake .shiftsim-value { color: #2f7a45; }
.shiftsim-card-retention .shiftsim-value { color: #1d7d8c; }
.shiftsim-card-credibility .shiftsim-value { color: #b07d18; }
.shiftsim-card-cpc .shiftsim-value { color: #6a4fb0; }

.shiftsim-sublabel {
    font-size: 0.74rem;
    color: #708d76;
    line-height: 1.35;
}

.shiftsim-uptake-target .shiftsim-value { color: #2f7a45; }
.shiftsim-uptake-fail .shiftsim-value { color: #c0392b; }

.shiftsim-credibility-greenwash { border-top-color: #c0392b; }
.shiftsim-credibility-greenwash .shiftsim-value { color: #c0392b; }

.shiftsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f5135;
    color: #eef8e8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.shiftsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.shiftsim-budget-over #budgetDisplay {
    color: #ffb3a1;
}

.shiftsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4ea35c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.05);
}

.shiftsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.shiftsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5135;
    margin-bottom: 6px;
}

.shiftsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #314639;
}

.shiftsim-briefing-text strong { color: #2f7a45; }
.shiftsim-briefing-text em { color: #9a4413; font-style: italic; }

.shiftsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.shiftsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5135;
    border-bottom: 2px solid #e6f0de;
    padding-bottom: 8px;
}

.shiftsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28412f;
    margin: 14px 0 6px;
}

.shiftsim-container select,
.shiftsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6ab;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fcf3;
    color: #1f2e22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.shiftsim-container select:focus,
.shiftsim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7a45;
    box-shadow: 0 0 0 3px rgba(47, 122, 69, 0.15);
}

.shiftsim-container select option {
    background-color: #ffffff;
    color: #1f2e22;
}

.shiftsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7a45;
}

.shiftsim-range-readout,
.shiftsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c5a3a;
    margin-top: 4px;
}

.shiftsim-range-readout span:last-child,
.shiftsim-alloc-readout span:nth-child(2) {
    color: #2f7a45;
    font-weight: 800;
}

.shiftsim-hint {
    font-size: 0.8rem;
    color: #708d76;
    margin-top: 4px;
    line-height: 1.4;
}

.shiftsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.shiftsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9ec;
    border: 1px solid #dceacf;
    border-radius: 9px;
    padding: 8px 12px;
}

.shiftsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28412f;
}

.shiftsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.shiftsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.shiftsim-container .btn-primary {
    background: linear-gradient(135deg, #2f7a45 0%, #4ea35c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 122, 69, 0.28);
}

.shiftsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.shiftsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6ab;
    color: #5e7a64;
}

.shiftsim-coach {
    background: #1f5135;
    color: #eef8e8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 81, 53, 0.22);
}

.shiftsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #9bd6a3;
    margin-bottom: 8px;
}

.shiftsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.shiftsim-coach-body strong { color: #ffe09a; }
.shiftsim-coach-body em { color: #ffc1ad; font-style: italic; }

.shiftsim-history,
.shiftsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9e8cf;
    box-shadow: 0 4px 14px rgba(31, 81, 53, 0.06);
}

.shiftsim-history h3,
.shiftsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5135;
}

.shiftsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28412f;
}

.shiftsim-container table#usfHistoryTable th {
    background: #eaf4e2;
    color: #1f5135;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e8c6;
}

.shiftsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef5e8;
}

.shiftsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fcf4;
}

.shiftsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .shiftsim-container {
        padding: 14px;
    }
    .shiftsim-header h1 {
        font-size: 1.7rem;
    }
    .shiftsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .shiftsim-value {
        font-size: 2rem;
    }
    .shiftsim-clock {
        margin-left: 0;
    }
    .shiftsim-period-counter {
        font-size: 0.88rem;
    }
    .shiftsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .shiftsim-alloc-row {
        flex-wrap: wrap;
    }
    .shiftsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .shiftsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.shift-cm { font-family: inherit; color: #1f2e22; padding: 4px 2px 2px; }
.shift-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f3f7ee,#e8f1e2); border-radius: 14px; border: 1px solid #d9e8cf; }
.shift-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #1f5135; }
.shift-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #6a836f; margin-left: 2px; }
.shift-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #6a836f; margin-top: 6px; }
.shift-cm-grade { font-size: 1.16rem; font-weight: 700; color: #2c5a3a; margin-top: 8px; }
.shift-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.shift-cm-badge-pass { background: #d4ecc6; color: #1f5135; }
.shift-cm-badge-miss { background: #ffe0d6; color: #b0361c; }
.shift-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.shift-cm-kpi { background: #ffffff; border: 1px solid #e4ede0; border-top: 3px solid #2f7a45; border-radius: 10px; padding: 12px 8px; text-align: center; }
.shift-cm-k-uptake { border-top-color: #2f7a45; }
.shift-cm-k-retention { border-top-color: #1d7d8c; }
.shift-cm-k-cred { border-top-color: #b07d18; }
.shift-cm-k-cpc { border-top-color: #6a4fb0; }
.shift-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1f2e22; line-height: 1.05; }
.shift-cm-k-uptake .shift-cm-kpi-val { color: #2f7a45; }
.shift-cm-k-retention .shift-cm-kpi-val { color: #1d7d8c; }
.shift-cm-k-cred .shift-cm-kpi-val { color: #b07d18; }
.shift-cm-k-cpc .shift-cm-kpi-val { color: #6a4fb0; }
.shift-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #3c4a40; margin-top: 5px; }
.shift-cm-kpi-sub { font-size: .64rem; color: #8a978d; margin-top: 2px; line-height: 1.25; }
.shift-cm-insights { margin: 16px 2px 6px; }
.shift-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #6a836f; margin: 0 0 8px; font-weight: 700; }
.shift-cm-insights ul { margin: 0; padding-left: 18px; }
.shift-cm-insights li { font-size: .86rem; line-height: 1.5; color: #2b3a30; margin-bottom: 7px; }
.shift-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #e4ede0; font-size: .72rem; color: #8a978d; text-align: center; font-style: italic; }
@media (max-width: 640px) { .shift-cm-kpis { grid-template-columns: repeat(2,1fr); } .shift-cm-scorenum { font-size: 2.6rem; } }

js:
(function() {
    'use strict';

    class ShiftAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Make the SHIFT`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Maple & Meadow Foods, CAD).
            this.BUDGET_CAP = 4.0;          // CA$4.0M fixed, no top-ups
            this.RETENTION_SPEND_CAP = 2.0; // CA$M into 90-day habit mechanics
            this.START_UPTAKE = 1;          // awareness-only moved <1%
            this.FAIL_BENCHMARK = 1;        // prior CA$6.5M campaigns moved <1%

            // Concept-correct answers (FACILITATOR DECISION TREE + COMMON ERRORS).
            this.TRUE_FRAME = `behaviour`;       // behaviour-change, not awareness
            this.TRUE_PRIORITY = `recycle`;      // repeated, low-observability habit at 28%
            this.TRUE_BARRIER = `friction`;      // friction & habit, not knowledge/caring
            this.LEVER_RECYCLE = `habit`;        // repeated, low-observability -> habit/defaults
            this.LEVER_WASTE = `tangibility`;    // private, hard to feel -> concrete feedback
            this.LEVER_SWITCH = `individual`;    // one-off, identity-laden -> individual self
            this.TRUE_MEASURE = `control`;       // control group + attributable behaviour
            this.TRUE_PITCH = `conversion`;      // behaviour -> levers -> measured conversion/retention
            this.TRUE_CLAIM = `specific`;        // substantiated, audit-proof
            this.TRUE_GATE = `retention`;        // scale only on 90-day retention vs control
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    uptake: this.START_UPTAKE,
                    retention: 0,
                    credibility: 50,
                    cpc: 0,            // CA$ per conversion (0 = not yet computed)
                    cpcSet: false,
                    reach: 0,          // millions of households exposed (vanity metric)
                    conversions: 0,    // thousands of behaviours changed
                    budgetUsed: 0,
                    overClaimed: false,
                    uptakeHistory: [this.START_UPTAKE],
                    retentionHistory: [0],
                    credibilityHistory: [50],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    frame: `behaviour`,
                    priority: `recycle`,
                    barrier: `friction`,
                    rigour: 50,
                    leverRecycle: `habit`,
                    leverWaste: `tangibility`,
                    leverSwitch: `social`,
                    backfire: 50,
                    onpack: 0.8,
                    instore: 0.8,
                    app: 0.8,
                    digital: 0.8,
                    partner: 0.8,
                    measure: `control`,
                    retentionSpend: 0.4,
                    pitch: `conversion`,
                    claim: `specific`,
                    gate: `retention`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const pr = document.getElementById(`priorityInput`);
                const ba = document.getElementById(`barrierInput`);
                const ri = document.getElementById(`rigourInput`);
                if (fr) decisions.frame = fr.value;
                if (pr) decisions.priority = pr.value;
                if (ba) decisions.barrier = ba.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const lr = document.getElementById(`leverRecycleInput`);
                const lw = document.getElementById(`leverWasteInput`);
                const ls = document.getElementById(`leverSwitchInput`);
                const bf = document.getElementById(`backfireInput`);
                if (lr) decisions.leverRecycle = lr.value;
                if (lw) decisions.leverWaste = lw.value;
                if (ls) decisions.leverSwitch = ls.value;
                if (bf) decisions.backfire = parseInt(bf.value, 10);
                if (!Number.isFinite(decisions.backfire) || decisions.backfire < 0 || decisions.backfire > 100) {
                    warn(`warn_backfire_range`); return false;
                }
            } else if (round === 3) {
                const ids = [`onpackInput`, `instoreInput`, `appInput`, `digitalInput`, `partnerInput`];
                const keys = [`onpack`, `instore`, `app`, `digital`, `partner`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                    if (!Number.isFinite(decisions[keys[i]]) || decisions[keys[i]] < 0) {
                        warn(`warn_alloc_negative`); return false;
                    }
                }
                const total = Math.round((decisions.onpack + decisions.instore + decisions.app + decisions.digital + decisions.partner) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
                const rs = document.getElementById(`retentionSpendInput`);
                if (rs) decisions.retentionSpend = parseFloat(rs.value);
                if (!Number.isFinite(decisions.retentionSpend) || decisions.retentionSpend < 0 || decisions.retentionSpend > this.RETENTION_SPEND_CAP) {
                    warn(`warn_retention_range`); return false;
                }
                const me = document.getElementById(`measureInput`);
                if (me) decisions.measure = me.value;
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const cl = document.getElementById(`claimInput`);
                const ga = document.getElementById(`gateInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (cl) decisions.claim = cl.value;
                if (ga) decisions.gate = ga.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let uptakeDelta = 0, retentionDelta = 0, credDelta = 0;
            let spend = 0, reachDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: behaviour-change problem, not an awareness gap (Common Error 1).
                // Uptake is a real-world % (failed campaigns <1%, strong ~12-16%) so deltas are small.
                if (d.frame === this.TRUE_FRAME) {
                    uptakeDelta += 2.0; credDelta += 6; coachKey = `coach_r1_frame_right`;
                } else if (d.frame === `awareness`) {
                    uptakeDelta -= 2.5; credDelta -= 6; coachKey = `coach_r1_awareness`;
                } else { // product
                    uptakeDelta -= 1.0; coachKey = `coach_r1_product`;
                }

                // Priority behaviour: recycle is the repeated, low-observability habit at 28% —
                // the sharpest target. "All three with one identical message" = one-size error.
                if (d.priority === this.TRUE_PRIORITY) {
                    uptakeDelta += 1.5; retentionDelta += 4;
                } else if (d.priority === `waste` || d.priority === `switch`) {
                    uptakeDelta += 0.4; // legitimate but not the sharpest first target
                } else { // all
                    uptakeDelta -= 2.5; credDelta -= 3; coachKey = `coach_r1_all`;
                }

                // Barrier: friction & habit is the real intention-action gap. Knowledge/caring
                // repeat the awareness fallacy.
                if (d.barrier === this.TRUE_BARRIER) {
                    uptakeDelta += 2.0; retentionDelta += 3;
                    if (d.frame === this.TRUE_FRAME) coachKey = `coach_r1_diag_sharp`;
                } else if (d.barrier === `knowledge`) {
                    uptakeDelta -= 2.5; coachKey = `coach_r1_knowledge`;
                } else { // caring
                    uptakeDelta -= 1.5; coachKey = `coach_r1_caring`;
                }

                // Rigour: measurable baselines vs vibes.
                if (d.rigour >= 70) { credDelta += 6; uptakeDelta += 0.5; }
                else if (d.rigour <= 25) { credDelta -= 6; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.frame === this.TRUE_FRAME && d.barrier === this.TRUE_BARRIER && d.priority === this.TRUE_PRIORITY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Match a SHIFT lever to each behaviour's barrier (Common Error 2: one-lever-fits-all).
                let matches = 0;

                // RECYCLE (low-observability, repeated) -> Habit. Social misfires (curb invisible);
                // Feelings is an awareness film.
                if (d.leverRecycle === this.LEVER_RECYCLE) { uptakeDelta += 2.0; retentionDelta += 6; matches++; }
                else if (d.leverRecycle === `social`) { uptakeDelta -= 1.5; coachKey = `coach_r2_rec_social`; }
                else { uptakeDelta -= 2.0; credDelta -= 2; coachKey = `coach_r2_rec_feelings`; }

                // FOOD WASTE (private, hard to feel) -> Tangibility. "Most people waste less" norm
                // can backfire; awareness reminder does nothing.
                if (d.leverWaste === this.LEVER_WASTE) { uptakeDelta += 1.8; retentionDelta += 4; matches++; }
                else if (d.leverWaste === `social`) { uptakeDelta -= 1.0; coachKey = `coach_r2_wst_social`; }
                else { uptakeDelta -= 1.8; coachKey = `coach_r2_wst_aware`; }

                // SWITCH (one-off, identity-laden) -> Individual self. Social is plausible-but-weaker;
                // habit re-ordering fits a repeated action, not a one-off identity choice.
                if (d.leverSwitch === this.LEVER_SWITCH) { uptakeDelta += 1.8; retentionDelta += 3; matches++; }
                else if (d.leverSwitch === `social`) { uptakeDelta += 0.4; coachKey = (coachKey === `coach_default`) ? `coach_r2_swt_social` : coachKey; }
                else { uptakeDelta -= 1.0; coachKey = `coach_r2_swt_habit`; }

                if (matches === 3) { uptakeDelta += 1.5; retentionDelta += 4; coachKey = `coach_r2_allmatched`; }
                else if (matches === 0) { coachKey = `coach_r2_onelever`; }

                // Backfire guard against norm misfire.
                if (d.backfire >= 70) { credDelta += 5; }
                else if (d.backfire <= 25) { credDelta -= 6; uptakeDelta -= 1.0; coachKey = `coach_r2_backfire`; }

                summaryKey = (matches === 3) ? `sum_r2_good` : (matches <= 1 ? `sum_r2_weak` : `sum_r2_mixed`);
            } else if (round === 3) {
                // Allocate CA$4.0M for conversion + retention, not reach (Common Error 3).
                spend = d.onpack + d.instore + d.app + d.digital + d.partner;

                // Reach is a vanity metric (digital is huge-reach, low-conversion).
                reachDelta = d.onpack * 0.4 + d.instore * 0.8 + d.app * 0.7 + d.digital * 2.4 + d.partner * 1.0;

                // Conversion potency per CA$M (concept: on-pack/app/partner convert; digital barely).
                // conv = thousands of behaviours changed -> drives CPC; uptake gets a small slice.
                const conv = d.onpack * 9 + d.instore * 6 + d.app * 8 + d.digital * 1.5 + d.partner * 7;
                ds.conversions += conv; // thousands of behaviours changed (for CPC)
                // Uptake % lift scaled to the conversion mix, centred so an even spread is middling.
                uptakeDelta += (conv - 24) * 0.30;

                // Over-weighting broad digital awareness = reach over conversion.
                if (d.digital >= 1.6) { uptakeDelta -= 2.0; credDelta -= 3; coachKey = `coach_r3_reach`; }
                else if (d.app >= 1.0 && d.partner >= 0.8 && d.digital <= 0.6) { uptakeDelta += 2.0; retentionDelta += 4; coachKey = `coach_r3_conversionmix`; }

                // Measurement design: control group makes uptake attributable and credible.
                if (d.measure === this.TRUE_MEASURE) { credDelta += 10; uptakeDelta += 1.0; if (coachKey === `coach_default`) coachKey = `coach_r3_control`; }
                else if (d.measure === `selfreport`) { credDelta -= 4; coachKey = `coach_r3_selfreport`; }
                else { credDelta -= 8; uptakeDelta -= 1.5; coachKey = `coach_r3_impressions`; }

                // 90-day habit mechanics drive retention (Common Error 5: launch spike, no stickiness).
                if (d.retentionSpend >= 0.6) { retentionDelta += 18; coachKey = (d.measure === this.TRUE_MEASURE) ? `coach_r3_retention` : coachKey; }
                else if (d.retentionSpend >= 0.3) { retentionDelta += 9; }
                else { retentionDelta += 2; coachKey = `coach_r3_noretention`; }

                summaryKey = (d.measure === this.TRUE_MEASURE && d.digital <= 0.6 && d.retentionSpend >= 0.6) ? `sum_r3_good` : (d.digital >= 1.6 ? `sum_r3_reach` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the plan vs the failed-campaign benchmark (Common Error 4 + greenwashing).
                switch (d.pitch) {
                    case `conversion`: uptakeDelta += 1.5; retentionDelta += 4; credDelta += 4; coachKey = `coach_r4_conversion`; break;
                    case `reach`: uptakeDelta -= 2.0; credDelta -= 4; coachKey = `coach_r4_reach`; break;
                    case `emotion`: uptakeDelta -= 1.0; credDelta -= 2; coachKey = `coach_r4_emotion`; break;
                }

                // The on-pack claim: substantiated tangibility vs greenwashing.
                switch (d.claim) {
                    case `specific`: credDelta += 14; retentionDelta += 2; break;
                    case `bold`: credDelta -= 14; uptakeDelta -= 1.0; ds.overClaimed = true; coachKey = `coach_r4_bold`; break;
                    case `vague`: credDelta -= 10; ds.overClaimed = true; coachKey = `coach_r4_vague`; break;
                }

                // Evidence gate before scale-up.
                switch (d.gate) {
                    case `retention`: retentionDelta += 8; credDelta += 6; if (d.pitch === this.TRUE_PITCH && d.claim === this.TRUE_CLAIM) coachKey = `coach_r4_gated`; break;
                    case `launch`: retentionDelta -= 8; credDelta -= 4; coachKey = `coach_r4_launchgate`; break;
                    case `none`: retentionDelta -= 12; credDelta -= 8; coachKey = `coach_r4_nogate`; break;
                }

                // Conviction nudges uptake.
                uptakeDelta += (d.conviction - 60) / 40;

                summaryKey = (d.pitch === this.TRUE_PITCH && d.claim === this.TRUE_CLAIM && d.gate === this.TRUE_GATE) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(Math.min(this.BUDGET_CAP, ds.budgetUsed + spend) * 10) / 10;
            ds.reach = Math.round((ds.reach + reachDelta) * 10) / 10;

            // KPIs move on their deltas (clamped, headroom preserved).
            ds.uptake = Math.max(0, Math.min(100, Math.round((ds.uptake + uptakeDelta) * 10) / 10));
            ds.retention = Math.max(0, Math.min(100, Math.round(ds.retention + retentionDelta)));
            ds.credibility = Math.max(0, Math.min(100, Math.round(ds.credibility + credDelta)));

            // Cost per conversion (CA$ per behaviour changed). conversions is in thousands;
            // budgetUsed is in CA$M -> CA$ per conversion = (budgetUsed * 1e6) / (conversions * 1e3).
            if (ds.conversions > 0 && ds.budgetUsed > 0) {
                ds.cpc = Math.round((ds.budgetUsed * 1000) / ds.conversions);
                ds.cpcSet = true;
            }

            ds.uptakeHistory.push(ds.uptake);
            ds.retentionHistory.push(ds.retention);
            ds.credibilityHistory.push(ds.credibility);
            // ── v1.1.0 fix: persist the composite where Express reporting reads it ──
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            const composite = this._composite(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;


            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                uptake: ds.uptake,
                uptakeDelta: Math.round(uptakeDelta * 10) / 10,
                retention: ds.retention,
                retentionDelta: Math.round(retentionDelta),
                credibility: ds.credibility,
                credibilityDelta: Math.round(credDelta),
                cpc: ds.cpcSet ? ds.cpc : null,
                reach: ds.reach,
                budgetUsed: ds.budgetUsed,
                score: composite,
                overClaimed: ds.overClaimed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`uptakeDisplay`, `domainState.uptake`, (v) => {
                const card = document.querySelector(`.shiftsim-card-uptake`);
                if (card) {
                    card.classList.toggle(`shiftsim-uptake-target`, Number(v) >= 12);
                    card.classList.toggle(`shiftsim-uptake-fail`, Number(v) <= self.FAIL_BENCHMARK + 1);
                }
                return (Math.round(Number(v) * 10) / 10) + `%`;
            });
            uiManager.bind(`retentionDisplay`, `domainState.retention`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => {
                const card = document.querySelector(`.shiftsim-card-credibility`);
                if (card) card.classList.toggle(`shiftsim-credibility-greenwash`, Number(v) < 35);
                return Math.round(Number(v));
            });
            uiManager.bind(`cpcDisplay`, `domainState.cpc`, (v) => {
                const ds = window.mySimulation.state.domainState;
                if (!ds || !ds.cpcSet) return `—`;
                return `CA$` + Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.shiftsim-budget-bar`);
                if (bar) bar.classList.toggle(`shiftsim-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return `CA$` + (Math.round(Number(v) * 10) / 10).toFixed(1) + `M / CA$4.0M`;
            });

            // Rigour slider readout.
            const ri = document.getElementById(`rigourInput`);
            const riReadout = document.getElementById(`rigourReadout`);
            if (ri && riReadout) {
                riReadout.textContent = ri.value;
                ri.addEventListener(`input`, function() { riReadout.textContent = ri.value; });
            }

            // Backfire slider readout.
            const bf = document.getElementById(`backfireInput`);
            const bfReadout = document.getElementById(`backfireReadout`);
            if (bf && bfReadout) {
                bfReadout.textContent = bf.value;
                bf.addEventListener(`input`, function() { bfReadout.textContent = bf.value; });
            }

            // Live budget allocation total (must hit CA$4.0M).
            const allocIds = [`onpackInput`, `instoreInput`, `appInput`, `digitalInput`, `partnerInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                if (allocReadout) allocReadout.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

