        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const uptake = Math.round(ds.uptake * 10) / 10;
            const retention = Math.round(ds.retention);
            const credibility = Math.round(ds.credibility);
            const cpc = ds.cpcSet ? ds.cpc : null;

            const beatBenchmark = uptake >= 8;
            const sticky = retention >= 55;
            const honest = credibility >= 65;
            const greenwash = ds.overClaimed || credibility < 35;

            // Composite: uptake scaled to /20 -> 0-100, plus retention and credibility.
            const uptakeScore = Math.min(100, uptake * 5);
            const composite = Math.round(uptakeScore * 0.40 + retention * 0.30 + credibility * 0.30);

            let performance = window.mySimulation.t(`perf_stalled`);
            if (beatBenchmark && sticky && honest && composite >= 72) performance = window.mySimulation.t(`perf_shift`);
            else if (beatBenchmark && sticky && !greenwash) performance = window.mySimulation.t(`perf_credible`);
            else if (beatBenchmark && greenwash) performance = window.mySimulation.t(`perf_greenwash`);
            else if (beatBenchmark) performance = window.mySimulation.t(`perf_spike`);
            else if (uptake > this.FAIL_BENCHMARK + 2) performance = window.mySimulation.t(`perf_short`);

            const insights = [];
            if (beatBenchmark && sticky && honest) insights.push(window.mySimulation.t(`insight_shift`));
            else if (beatBenchmark && greenwash) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (beatBenchmark) insights.push(window.mySimulation.t(`insight_spike`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (retention < 45) insights.push(window.mySimulation.t(`insight_decay`));
            if (credibility < 45) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (cpc !== null && cpc > 0 && cpc <= 12) insights.push(window.mySimulation.t(`insight_efficient`));
            if (beatBenchmark && sticky && honest && retention >= 65) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                uptake: uptake,
                retention: retention,
                credibility: credibility,
                cpc: cpc,
                beatBenchmark: beatBenchmark,
                greenwash: greenwash,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── v1.1.0 fix: persist composite score + localized completion debrief ──
        _composite(ds) {
            // Verbatim mirror of getPerformanceSummary()'s composite so the persisted
            // score equals the on-screen composite (no scoring change).
            const uptake = Math.round((ds.uptake || 0) * 10) / 10;
            const retention = Math.round(ds.retention || 0);
            const credibility = Math.round(ds.credibility || 0);
            const uptakeScore = Math.min(100, uptake * 5);
            return Math.round(uptakeScore * 0.40 + retention * 0.30 + credibility * 0.30);
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const composite = (typeof s.composite === `number`) ? s.composite : 0;
            const grade = s.performance || ``;
            const beat = !!s.beatBenchmark;
            const uptake = (s.uptake != null) ? s.uptake : 0;
            const retention = (s.retention != null) ? s.retention : 0;
            const credibility = (s.credibility != null) ? s.credibility : 0;
            const cpc = (s.cpc != null) ? s.cpc : null;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const badgeClass = beat ? `shift-cm-badge-pass` : `shift-cm-badge-miss`;
            const badgeText = beat ? t(`cm_badge_beat`) : t(`cm_badge_missed`);
            const cpcDisplay = (cpc !== null && cpc > 0) ? (`CA$` + cpc) : `—`;

            const kpi = (label, val, sub, cls) => `
                <div class="shift-cm-kpi ${cls}">
                    <div class="shift-cm-kpi-val">${val}</div>
                    <div class="shift-cm-kpi-label">${label}</div>
                    <div class="shift-cm-kpi-sub">${sub}</div>
                </div>`;

            let insightHtml = ``;
            insights.forEach((it) => { insightHtml += `<li>${it}</li>`; });

            return `
                <div class="shift-cm">
                    <div class="shift-cm-scoreblock">
                        <div class="shift-cm-scorenum">${composite}<span class="shift-cm-scoremax">/100</span></div>
                        <div class="shift-cm-scorelabel">${t(`cm_score_label`)}</div>
                        <div class="shift-cm-grade">${grade}</div>
                        <span class="shift-cm-badge ${badgeClass}">${badgeText}</span>
                    </div>
                    <div class="shift-cm-kpis">
                        ${kpi(t(`uptake_label`), uptake + `%`, t(`uptake_sub`), `shift-cm-k-uptake`)}
                        ${kpi(t(`retention_label`), retention + `%`, t(`retention_sub`), `shift-cm-k-retention`)}
                        ${kpi(t(`credibility_label`), credibility, t(`credibility_sub`), `shift-cm-k-cred`)}
                        ${kpi(t(`cpc_label`), cpcDisplay, t(`cpc_sub`), `shift-cm-k-cpc`)}
                    </div>
                    ${insightHtml ? `<div class="shift-cm-insights"><h6>${t(`cm_insights_title`)}</h6><ul>${insightHtml}</ul></div>` : ``}
                    <div class="shift-cm-footer">${t(`cm_footer`)}</div>
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overClaimed || ds.credibility < 35) return window.mySimulation.t(`hint_greenwash`);
            if (ds.retention < 30 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_retention`);
            if (ds.uptake <= this.FAIL_BENCHMARK + 2 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_uptake`);
            if (ds.reach >= 5 && ds.uptake < 8) return window.mySimulation.t(`hint_reach`);
            if (ds.uptake >= 10 && ds.retention >= 55 && ds.credibility >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

