                    bar_knowledge:          `Knowledge — consumers don't yet know recycling is good`,
                    bar_caring:             `Caring — consumers don't care about the planet enough yet`,
                    r1_rigour_label:        `How rigorously does the team set measurable behavioural baselines (vs vibes)? (%)`,
                    r1_rigour_readout:      `Discipline in setting baselines to move:`,

                    r2_recycle_label:       `RECYCLE (low-observability, repeated): which SHIFT lever fits the barrier?`,
